// Most generated IDs and text need no escaping. Keep JSON's full behavior for
// other values, controls and UTF-16 surrogates, plus script-element protection.
const requiresEscaping = /["\\<\u0000-\u001f\u2028\u2029\ud800-\udfff]/;
export const quote = (value) => typeof value === 'string' && !requiresEscaping.test(value)
    ? '"' + value + '"'
    : JSON.stringify(value).replace(/[<\u2028\u2029]/g, character => character === '<' ? '\\u003c' : character === '\u2028' ? '\\u2028' : '\\u2029');
export const header = '// Generated by fasti18n. Do not edit.\n';
/** Rewrite internal identifiers in compiler-owned code, skipping JSON strings. */
export function rewriteGeneratedIdentifiers(source, rename) {
    return source.replace(/"(?:[^"\\]|\\.)*"|(\$f\d+(?:Cache)?|\$literal|\$parts)\b/g, (token, identifier) => identifier ? rename(identifier) : token);
}
/** Substitute compiler-owned text parameters without touching quoted user data.
 * Fold a following quoted constant too, so inlined validation labels match
 * direct error strings. Joining JSON string payloads preserves their escapes.
 */
export function substituteTextParameters(source, values) {
    if (source.startsWith('{const $c'))
        source = '(()=>' + source + ')()';
    const substituted = source.replace(/"(?:[^"\\]|\\.)*"|\$s(\d+)\b(?:\+("(?:[^"\\]|\\.)*"))?/g, (token, index, suffix) => {
        if (index === undefined)
            return token;
        const value = quote(values[Number(index)]);
        return suffix === undefined ? value : value.slice(0, -1) + suffix.slice(1);
    });
    if (!substituted.startsWith('(()=>{const $c'))
        return substituted;
    // A one-off projection can evaluate compiler-owned string initializers at
    // build time and recover exactly the direct, folded function expression.
    let body = substituted.slice('(()=>{'.length);
    const constants = new Map();
    for (;;) {
        const declaration = /^const (\$c\d+)=("(?:[^"\\]|\\.)*"(?:\+"(?:[^"\\]|\\.)*")*);/.exec(body);
        if (!declaration)
            break;
        constants.set(declaration[1], [...declaration[2].matchAll(/"(?:[^"\\]|\\.)*"/g)].map(match => JSON.parse(match[0])).join(''));
        body = body.slice(declaration[0].length);
    }
    if (!body.startsWith('return ') || !body.endsWith(';})()'))
        throw new Error('Invalid generated literal initializers.');
    return body.slice('return '.length, -';})()'.length).replace(/"(?:[^"\\]|\\.)*"|(\$c\d+)\b/g, (token, identifier) => identifier === undefined ? token : quote(constants.get(identifier)));
}
